import { readConfig, requirePrivateKey, getFomoToken } from "../lib/config.js"
import { getPublicClient, getWalletClient } from "../lib/client.js"
import { output, log, fatal } from "../lib/output.js"
import { getFlagValue } from "../lib/args.js"
import {
  PORTAL_ADDRESSES, PORTAL_ABI, NATIVE_BNB,
  PANCAKE_ROUTER_ADDRESSES, PANCAKE_ROUTER_ABI, WBNB_ADDRESSES,
  TOKEN_STATUS, queryTokenStatus,
} from "../lib/flap.js"
import { parseBigInt } from "../lib/utils.js"

export async function buy(args: string[]) {
  const amountStr = getFlagValue(args, "--amount")
  if (!amountStr) fatal("Missing --amount <bnb_wei>. Usage: fomo3d buy --amount 10000000000000000 (0.01 BNB)")

  const bnbAmount = parseBigInt(amountStr, "amount")
  if (bnbAmount <= 0n) fatal("Amount must be positive")

  const config = readConfig()
  const pk = requirePrivateKey(config)
  const publicClient = getPublicClient(config.network, config.rpcUrl)
  const walletClient = getWalletClient(pk, config.network, config.rpcUrl)
  const fomoToken = getFomoToken(config)
  const portal = PORTAL_ADDRESSES[config.network]
  const account = walletClient.account!.address

  // 检查 BNB 余额
  const bnbBalance = await publicClient.getBalance({ address: account })
  if (bnbBalance < bnbAmount) {
    fatal(`Insufficient BNB balance: have ${bnbBalance}, need ${bnbAmount}`)
  }

  // 查代币市场状态
  const { statusCode, tokenState } = await queryTokenStatus(publicClient, portal, fomoToken)
  if (!tokenState) log("Token not found on FLAP Portal, using PancakeSwap...")
  const statusName = TOKEN_STATUS[statusCode] ?? "Unknown"

  if (statusCode === 1) {
    // 内盘（Tradable）— 直接调用 Portal.swapExactInput 用 BNB
    log(`Buying FOMO on 内盘 (Portal) with ${bnbAmount} BNB (wei)...`)
    const hash = await walletClient.writeContract({
      address: portal,
      abi: PORTAL_ABI,
      functionName: "swapExactInput",
      args: [{
        inputToken: NATIVE_BNB,
        outputToken: fomoToken,
        inputAmount: bnbAmount,
        minOutputAmount: 0n,
        permitData: "0x",
      }],
      value: bnbAmount,
      chain: walletClient.chain,
    })

    log(`Transaction: ${hash}`)
    const receipt = await publicClient.waitForTransactionReceipt({ hash })

    output({
      txHash: hash,
      blockNumber: Number(receipt.blockNumber),
      status: receipt.status,
      bnbSpent: bnbAmount.toString(),
      token: fomoToken,
      market: "内盘 (Portal)",
    }, (d) => {
      log(`\nBuy ${d.status === "success" ? "successful" : "failed"}!`)
      log(`BNB spent: ${d.bnbSpent}`)
      log(`Market: ${d.market}`)
      log(`Block: ${d.blockNumber}`)
      log("")
    })
  } else if (statusCode === 4) {
    // 外盘（DEX）— PancakeSwap V2 Router (swapExactETHForTokens)
    const pancakeRouter = PANCAKE_ROUTER_ADDRESSES[config.network]
    const wbnb = WBNB_ADDRESSES[config.network]
    log(`Buying FOMO on 外盘 (PancakeSwap) with ${bnbAmount} BNB (wei)...`)
    const deadline = BigInt(Math.floor(Date.now() / 1000) + 300) // 5 分钟

    const hash = await walletClient.writeContract({
      address: pancakeRouter,
      abi: PANCAKE_ROUTER_ABI,
      functionName: "swapExactETHForTokensSupportingFeeOnTransferTokens",
      args: [0n, [wbnb, fomoToken], account, deadline],
      value: bnbAmount,
      chain: walletClient.chain,
    })

    log(`Transaction: ${hash}`)
    const receipt = await publicClient.waitForTransactionReceipt({ hash })

    output({
      txHash: hash,
      blockNumber: Number(receipt.blockNumber),
      status: receipt.status,
      bnbSpent: bnbAmount.toString(),
      token: fomoToken,
      market: "外盘 (PancakeSwap)",
    }, (d) => {
      log(`\nBuy ${d.status === "success" ? "successful" : "failed"}!`)
      log(`BNB spent: ${d.bnbSpent}`)
      log(`Market: ${d.market}`)
      log(`Block: ${d.blockNumber}`)
      log("")
    })
  } else {
    fatal(`Token is not tradable. Status: ${statusName} (${statusCode})`)
  }
}

import { readConfig, requirePrivateKey, getDiamondAddress } from "../lib/config.js"
import { getPublicClient, getWalletClient } from "../lib/client.js"
import { FOMO3D_ABI } from "../lib/contracts.js"
import { output, log, fatal } from "../lib/output.js"

export async function endRound(_args: string[]) {
  const config = readConfig()
  const pk = requirePrivateKey(config)
  const publicClient = getPublicClient(config.network, config.rpcUrl)
  const walletClient = getWalletClient(pk, config.network, config.rpcUrl)
  const diamond = getDiamondAddress(config)

  // 检查倒计时
  const countdown = await publicClient.readContract({
    address: diamond, abi: FOMO3D_ABI, functionName: "getCountdownRemaining",
  }) as bigint

  if (countdown > 0n) {
    fatal(`Round not expired yet. ${countdown} seconds remaining.`)
  }

  log("Ending round and distributing prizes...")
  const hash = await walletClient.writeContract({
    address: diamond,
    abi: FOMO3D_ABI,
    functionName: "endRoundAndDistribute",
    chain: walletClient.chain,
  })

  log(`Transaction: ${hash}`)
  const receipt = await publicClient.waitForTransactionReceipt({ hash })

  output({
    txHash: hash,
    blockNumber: Number(receipt.blockNumber),
    status: receipt.status,
  }, (d) => {
    log(`\nEnd round ${d.status === "success" ? "successful" : "failed"}!`)
    log(`Block: ${d.blockNumber}`)
    log("")
  })
}

import { readConfig, requirePrivateKey, getDiamondAddress } from "../lib/config.js"
import { getPublicClient, getWalletClient } from "../lib/client.js"
import { FOMO3D_ABI } from "../lib/contracts.js"
import { output, log, fatal } from "../lib/output.js"

export async function exit(_args: string[]) {
  const config = readConfig()
  const pk = requirePrivateKey(config)
  const publicClient = getPublicClient(config.network, config.rpcUrl)
  const walletClient = getWalletClient(pk, config.network, config.rpcUrl)
  const diamond = getDiamondAddress(config)
  const account = walletClient.account!.address

  // 检查暂停
  const isPaused = await publicClient.readContract({
    address: diamond, abi: FOMO3D_ABI, functionName: "isPaused",
  }) as boolean
  if (isPaused) fatal("Game is paused")

  // 检查玩家状态
  const playerInfo = await publicClient.readContract({
    address: diamond, abi: FOMO3D_ABI, functionName: "getPlayerInfo", args: [account],
  }) as readonly [bigint, bigint, number, bigint, boolean]

  if (playerInfo[3] === 0n) fatal("You have no shares")
  if (playerInfo[4]) fatal("Already exited this round")

  log("Exiting game...")
  const hash = await walletClient.writeContract({
    address: diamond,
    abi: FOMO3D_ABI,
    functionName: "exitGame",
    chain: walletClient.chain,
  })

  log(`Transaction: ${hash}`)
  const receipt = await publicClient.waitForTransactionReceipt({ hash })

  output({
    txHash: hash,
    blockNumber: Number(receipt.blockNumber),
    status: receipt.status,
    shares: playerInfo[3].toString(),
  }, (d) => {
    log(`\nExit ${d.status === "success" ? "successful" : "failed"}!`)
    log(`Shares exited: ${d.shares}`)
    log(`Block: ${d.blockNumber}`)
    log("")
  })
}

import { readConfig, requirePrivateKey } from "../lib/config.js"
import { getWalletClient } from "../lib/client.js"
import { output, log, fatal } from "../lib/output.js"

// Supabase Edge Function URL（testnet only）
const FAUCET_URL = "https://ukppfcznttdfkqzqxrse.supabase.co/functions/v1/faucet"

export async function faucet(args: string[]) {
  const config = readConfig()

  if (config.network !== "testnet") {
    fatal("Faucet is only available on testnet.")
  }

  const pk = requirePrivateKey(config)
  const walletClient = getWalletClient(pk, config.network, config.rpcUrl)
  const account = walletClient.account!.address

  log(`Claiming 10000 FOMO tokens for ${account}...`)

  const res = await fetch(FAUCET_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ address: account }),
  })

  const data = await res.json()

  if (!res.ok) {
    if (data.retryAfter) {
      fatal(`Rate limited. Retry in ${Math.ceil(data.retryAfter / 60)} minutes.`)
    }
    fatal(data.error ?? `Faucet error (${res.status})`)
  }

  output({
    txHash: data.txHash,
    amount: data.amount,
    token: data.token,
    account,
  }, (d) => {
    log(`\nFaucet claim successful!`)
    log(`Amount: ${d.amount} FOMO`)
    log(`Tx: ${d.txHash}`)
    log("")
  })
}

import type { Address } from "viem"
import { readConfig, requirePrivateKey, getDiamondAddress } from "../lib/config.js"
import { getPublicClient, getWalletClient } from "../lib/client.js"
import { FOMO3D_ABI } from "../lib/contracts.js"
import { output, log } from "../lib/output.js"
import { getFlagValue } from "../lib/args.js"

export async function player(args: string[]) {
  const config = readConfig()
  const publicClient = getPublicClient(config.network, config.rpcUrl)
  const diamond = getDiamondAddress(config)

  // 确定地址
  let address: Address
  const addrArg = getFlagValue(args, "--address")
  if (addrArg) {
    address = addrArg as Address
  } else {
    const pk = requirePrivateKey(config)
    const wc = getWalletClient(pk, config.network, config.rpcUrl)
    address = wc.account!.address
  }

  const [playerInfo, pendingEarnings, pendingWithdrawal] = await Promise.all([
    publicClient.readContract({
      address: diamond, abi: FOMO3D_ABI, functionName: "getPlayerInfo", args: [address],
    }) as Promise<readonly [bigint, bigint, number, bigint, boolean]>,
    publicClient.readContract({
      address: diamond, abi: FOMO3D_ABI, functionName: "getPlayerPendingEarnings", args: [address],
    }) as Promise<bigint>,
    publicClient.readContract({
      address: diamond, abi: FOMO3D_ABI, functionName: "getPendingWithdrawal", args: [address],
    }) as Promise<bigint>,
  ])

  const data = {
    address,
    network: config.network,
    earningsPerShare: playerInfo[0].toString(),
    accumulatedEarnings: playerInfo[1].toString(),
    roundNumber: Number(playerInfo[2]),
    shares: playerInfo[3].toString(),
    hasExited: playerInfo[4],
    pendingEarnings: pendingEarnings.toString(),
