export async function slotDeposit(args: string[]) {
  const amountStr = getFlagValue(args, "--amount")
  if (!amountStr) fatal("Missing --amount <n>. Usage: fomo3d slot deposit --amount 1000000000000000000")

  const amount = BigInt(amountStr)
  if (amount <= 0n) fatal("Amount must be positive")

  const config = readConfig()
  const pk = requirePrivateKey(config)
  const publicClient = getPublicClient(config.network, config.rpcUrl)
  const walletClient = getWalletClient(pk, config.network, config.rpcUrl)
  const slotDiamond = getSlotDiamondAddress(config)

  // 获取 token 地址
  const slotConfig = await publicClient.readContract({
    address: slotDiamond, abi: SLOT_ABI, functionName: "getSlotConfig",
  }) as { token: Address }

  // 自动 approve
  await ensureAllowance(publicClient, walletClient, slotConfig.token, slotDiamond, amount)

  log(`Depositing ${amount} tokens to prize pool...`)
  log("WARNING: Deposited tokens are permanently locked. You earn dividends from shares.")

  const hash = await walletClient.writeContract({
    address: slotDiamond,
    abi: SLOT_ABI,
    functionName: "deposit",
    args: [amount],
    chain: walletClient.chain,
  })

  log(`Transaction: ${hash}`)
  const receipt = await publicClient.waitForTransactionReceipt({ hash })

  output({
    txHash: hash,
    blockNumber: Number(receipt.blockNumber),
    status: receipt.status,
    amount: amount.toString(),
    warning: "Tokens permanently locked. You earn dividend shares.",
  }, (d) => {
    log(`\nDeposit ${d.status === "success" ? "successful" : "failed"}!`)
    log(`Amount: ${d.amount}`)
    log(`Block: ${d.blockNumber}`)
    log("")
  })
}

import type { Address } from "viem"
import { readConfig, requirePrivateKey, getSlotDiamondAddress } from "../lib/config.js"
import { getPublicClient, getWalletClient } from "../lib/client.js"
import { SLOT_ABI, VRF_FEE_FALLBACK } from "../lib/contracts.js"
import { ensureAllowance } from "../lib/erc20.js"
import { output, log, fatal } from "../lib/output.js"
import { getFlagValue } from "../lib/args.js"

export async function slotSpin(args: string[]) {
  const betStr = getFlagValue(args, "--bet")
  if (!betStr) fatal("Missing --bet <amount>. Usage: fomo3d slot spin --bet 1000000000000000000")

  const betAmount = BigInt(betStr)
  if (betAmount <= 0n) fatal("Bet amount must be positive")

  const config = readConfig()
  const pk = requirePrivateKey(config)
  const publicClient = getPublicClient(config.network, config.rpcUrl)
  const walletClient = getWalletClient(pk, config.network, config.rpcUrl)
  const slotDiamond = getSlotDiamondAddress(config)

  // 获取配置
  const slotConfig = await publicClient.readContract({
    address: slotDiamond, abi: SLOT_ABI, functionName: "getSlotConfig",
  }) as { token: Address; minBet: bigint; maxBet: bigint; vrfFee: bigint }

  if (betAmount < slotConfig.minBet) fatal(`Bet too small. Min: ${slotConfig.minBet}`)
  if (betAmount > slotConfig.maxBet) fatal(`Bet too large. Max: ${slotConfig.maxBet}`)

  // 自动 approve
  await ensureAllowance(publicClient, walletClient, slotConfig.token, slotDiamond, betAmount)

  // spin（payable，附带 VRF 费用）
  const vrfFee = slotConfig.vrfFee > 0n ? slotConfig.vrfFee : VRF_FEE_FALLBACK
  log(`Spinning with bet ${betAmount}, VRF fee ${vrfFee}...`)

  const hash = await walletClient.writeContract({
    address: slotDiamond,
    abi: SLOT_ABI,
    functionName: "spin",
    args: [betAmount],
    value: vrfFee,
    chain: walletClient.chain,
  })

  log(`Transaction: ${hash}`)
  const receipt = await publicClient.waitForTransactionReceipt({ hash })

  output({
    txHash: hash,
    blockNumber: Number(receipt.blockNumber),
    status: receipt.status,
    betAmount: betAmount.toString(),
    vrfFee: vrfFee.toString(),
    note: "Spin requested. VRF callback pending (1-3 blocks). Check result with 'fomo3d slot status' or player info.",
  }, (d) => {
    log(`\nSpin ${d.status === "success" ? "requested" : "failed"}!`)
    log(`Bet: ${d.betAmount}`)
    log(d.note)
    log("")
  })
}

import { readConfig, getSlotDiamondAddress } from "../lib/config.js"
import { getPublicClient } from "../lib/client.js"
import { SLOT_ABI } from "../lib/contracts.js"
import { output, log, fatal } from "../lib/output.js"

export async function slotStatus(_args: string[]) {
  const config = readConfig()
  const publicClient = getPublicClient(config.network, config.rpcUrl)
  const slotDiamond = getSlotDiamondAddress(config)

  const [slotConfig, isPaused] = await Promise.all([
      publicClient.readContract({ address: slotDiamond, abi: SLOT_ABI, functionName: "getSlotConfig" }),
      publicClient.readContract({ address: slotDiamond, abi: SLOT_ABI, functionName: "isPaused" }),
    ])

    // SlotConfig 是一个 struct，viem 返回对象
    const sc = slotConfig as {
      token: string; minBet: bigint; maxBet: bigint; prizePool: bigint;
      totalShares: bigint; devFeeBps: number; dividendBps: number; vrfFee: bigint;
      totalSpins: bigint; totalBetAmount: bigint; totalWinAmount: bigint;
      totalDividendsDistributed: bigint;
    }

    const data = {
      network: config.network,
      paused: isPaused as boolean,
      token: sc.token,
      minBet: sc.minBet.toString(),
      maxBet: sc.maxBet.toString(),
      prizePool: sc.prizePool.toString(),
      totalShares: sc.totalShares.toString(),
      devFeeBps: Number(sc.devFeeBps),
      dividendBps: Number(sc.dividendBps),
      vrfFee: sc.vrfFee.toString(),
      stats: {
        totalSpins: sc.totalSpins.toString(),
        totalBetAmount: sc.totalBetAmount.toString(),
        totalWinAmount: sc.totalWinAmount.toString(),
        totalDividendsDistributed: sc.totalDividendsDistributed.toString(),
      },
    }

    output(data, (d) => {
      log(`\n=== Slot Machine (${d.network}) ===`)
      log(`Paused:      ${d.paused}`)
      log(`Prize Pool:  ${d.prizePool}`)
      log(`Min Bet:     ${d.minBet}`)
      log(`Max Bet:     ${d.maxBet}`)
      log(`VRF Fee:     ${d.vrfFee} wei`)
      log(`Dividend:    ${d.dividendBps / 100}%`)
      log(`Dev Fee:     ${d.devFeeBps / 100}%`)
      log(`Total Spins: ${d.stats.totalSpins}`)
      log(`Total Bet:   ${d.stats.totalBetAmount}`)
      log(`Total Won:   ${d.stats.totalWinAmount}`)
      log("")
    })
}

import { isAddress, getAddress, formatUnits, type Address } from "viem"
import { readConfig, getFomoToken } from "../lib/config.js"
import { getPublicClient } from "../lib/client.js"
import { getTokenBalance } from "../lib/erc20.js"
import { output, log, fatal } from "../lib/output.js"
